mapper.select:
SELECT * FROM ( SELECT FBM.YYYYMM , DV.DIVISION_CODE , DV.DIVISION_NAME , IM.ITEM_CODE AS PRODUCT_CODE , IM.ITEM_NAME AS PRODUCT_NAME , FBM.HS_CODE FROM FTA_BOM_MST FBM INNER JOIN DIVISION DV ON DV.DIVISION_CODE = FBM.DIVISION_CODE AND DV.COMPANY_CODE = FBM.COMPANY_CODE AND DV.STATUS = 'Y' INNER JOIN ITEM_MST IM ON IM.ITEM_CODE = FBM.PRODUCT_CODE AND IM.COMPANY_CODE = FBM.COMPANY_CODE WHERE FBM.COMPANY_CODE = #{company_code} ) WHERE 1=1
AND YYYYMM BETWEEN #{from_date} AND #{to_date}
AND (PRODUCT_CODE ILIKE '%' || #{product} || '%' OR PRODUCT_NAME ILIKE '%' || #{product} || '%' )
AND DIVISION_CODE = #{division_code}
ORDER BY YYYYMM, DIVISION_CODE, PRODUCT_CODE

SELECT * FROM ( SELECT FBD.YYYYMM , IM.ITEM_CODE , IM.ITEM_NAME , IM.UNIT , FBD.HS_CODE , FBD.REQ_QTY FROM FTA_BOM_DTL FBD INNER JOIN DIVISION DV ON DV.DIVISION_CODE = FBD.DIVISION_CODE AND DV.COMPANY_CODE = FBD.COMPANY_CODE AND DV.STATUS = 'Y' INNER JOIN ITEM_MST IM ON IM.ITEM_CODE = FBD.ITEM_CODE AND IM.COMPANY_CODE = FBD.COMPANY_CODE WHERE FBD.COMPANY_CODE = #{company_code}
AND FBD.YYYYMM = #{yyyymm}
AND FBD.PRODUCT_CODE = #{product_code}
AND FBD.DIVISION_CODE = #{division_code}
) WHERE 1=1

SELECT PL.*, V.VENDOR_NAME FROM ( SELECT PL.VENDOR_CODE , PL.COMPANY_CODE , MAX(PL.WAREHOUSING_DATE) AS LAST_WAREHOUSING_DATE FROM PO_LEDGER PL WHERE PL.COMPANY_CODE = #{company_code}
AND PL.ITEM_CODE = #{item_code}
AND PL.WAREHOUSING_DATE BETWEEN to_char(TO_DATE(#{yyyymm}, 'YYYYMM') - INTERVAL '6 month', 'YYYYMM') AND #{yyyymm}
GROUP BY PL.COMPANY_CODE, PL.VENDOR_CODE ) PL INNER JOIN VENDOR V ON PL.COMPANY_CODE = V.COMPANY_CODE AND PL.VENDOR_CODE = V.VENDOR_CODE
